H.background();
const n = Math.max(3, Math.round(P.n));
const cx = H.W*0.40, cy = H.H*0.56, R = 130;
const rot = -Math.PI/2;
const pts = [];
for (let i = 0; i < n; i++){
  const a = rot + i*2*Math.PI/n;
  pts.push([cx + R*Math.cos(a), cy + R*Math.sin(a)]);
}
const ext = 360/n;
H.text("Exterior angles of any polygon sum to 360°", 24, 30, {color:H.colors.ink, size:18, weight:700});
H.text("Walking the whole boundary turns you through exactly one full turn.", 24, 52, {color:H.colors.sub, size:13});
H.path(pts, {close:true, fill:"rgba(124,196,255,0.10)", color:H.colors.accent, width:2.5});
for (let i = 0; i < n; i++){
  const A = pts[i], B = pts[(i+1)%n];
  const dx = B[0]-A[0], dy = B[1]-A[1];
  const L = Math.hypot(dx,dy) || 1;
  const ux = dx/L, uy = dy/L;
  H.arrow(B[0]-ux*22, B[1]-uy*22, B[0]+ux*26, B[1]+uy*26, {color:H.colors.accent2, width:2});
}
const dialX = H.W*0.82, dialY = H.H*0.56, dR = 90;
H.circle(dialX, dialY, dR, {stroke:H.colors.grid, width:1.5});
const k = Math.floor((t*0.7) % n);
const turned = (k+1)*ext;
for (let i = 0; i <= k; i++){
  const a0 = -Math.PI/2 + i*ext*Math.PI/180;
  const a1 = -Math.PI/2 + (i+1)*ext*Math.PI/180;
  const wedge = [[dialX,dialY]];
  for (let s = 0; s <= 10; s++){
    const a = a0 + (a1-a0)*s/10;
    wedge.push([dialX + dR*Math.cos(a), dialY + dR*Math.sin(a)]);
  }
  H.path(wedge, {close:true, fill:"rgba(244,162,89,0.22)", color:H.colors.accent2, width:1});
}
H.text("each exterior = 360 / " + n + " = " + ext.toFixed(1) + "°", 24, 76, {color:H.colors.accent2, size:13});
H.text("turned so far = " + turned.toFixed(0) + "° of 360°", 24, 96, {color:H.colors.good, size:13});
H.text("full turn", dialX, dialY+dR+20, {color:H.colors.sub, size:12, align:"center"});
